package com.eidolon.sc.mobile;
import android.content.Context;import org.json.*;import java.util.*;import java.time.*;import java.net.URLEncoder;import java.io.*;
/** Original upstream WGS-84 place pool. It is not live character tracking. */
final class PlacePool {
 static final Set<String> INDOOR=new HashSet<>(Arrays.asList("cafe","books","mall","museum","bath","venue"));
 static volatile JSONArray cached;
 static JSONArray all(Context c)throws Exception{if(cached==null)synchronized(PlacePool.class){if(cached==null){try(InputStream in=c.getAssets().open("places.json")){JSONArray rows=new JSONObject(new String(StoryFiles.read(in,1024*1024),"UTF-8")).getJSONArray("places");Set<String> ids=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject p=rows.getJSONObject(i);SocialData.coordinate(p.getDouble("lat"),p.getDouble("lon"));if(!ids.add(p.getString("id"))||p.getString("name").trim().isEmpty())throw new IOException("地点资料无效");}cached=rows;}}}return cached;}
 static JSONObject profiles(Context c)throws Exception{try(InputStream in=c.getAssets().open("social-profiles.json")){return new JSONObject(new String(StoryFiles.read(in,512*1024),"UTF-8")).getJSONObject("profiles");}}
 static Set<String> venues(JSONObject profile,long now)throws Exception{Set<String> out=new HashSet<>();if(profile==null)return out;JSONArray a=profile.optJSONArray("liveDays");if(a==null)return out;LocalDate today=Instant.ofEpochMilli(now).atZone(SocialData.TOKYO).toLocalDate();for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);LocalDate date=LocalDate.parse(r.getString("date"));if(date.getYear()<today.getYear()&&date.getMonth()==today.getMonth()&&date.getDayOfMonth()==today.getDayOfMonth())out.add(r.getString("venue"));}return out;}
 static JSONArray anniversaries(JSONObject profile,long now)throws Exception{JSONArray out=new JSONArray();if(profile==null)return out;JSONArray a=profile.optJSONArray("liveDays");if(a==null)return out;LocalDate today=Instant.ofEpochMilli(now).atZone(SocialData.TOKYO).toLocalDate();for(int i=a.length()-1;i>=0&&out.length()<5;i--){JSONObject r=a.getJSONObject(i);LocalDate date=LocalDate.parse(r.getString("date"));if(date.getYear()<today.getYear()&&date.getMonth()==today.getMonth()&&date.getDayOfMonth()==today.getDayOfMonth())out.put(new JSONObject(r.toString()));}return out;}
 static String slot(int hour){return hour<6?"":hour<12?"morning":hour<18?"afternoon":"evening";}
 static boolean nearby(JSONObject place){String area=place.optString("area");return area.startsWith("神奈川県")||area.startsWith("千葉県")||area.startsWith("埼玉県");}
 static JSONArray draw(JSONArray all,String who,JSONArray likes,Set<String> used,long at,boolean wet,Set<String> within,Random r)throws Exception{
  return draw(all,who,likes,used,at,wet,within,Collections.emptySet(),r);
 }
 static JSONArray draw(JSONArray all,String who,JSONArray likes,Set<String> used,long at,boolean wet,Set<String> within,Set<String> venues,Random r)throws Exception{
  ZonedDateTime time=Instant.ofEpochMilli(at).atZone(SocialData.TOKYO);String season=time.getMonthValue()>=3&&time.getMonthValue()<=5?"spring":time.getMonthValue()>=6&&time.getMonthValue()<=8?"summer":time.getMonthValue()>=9&&time.getMonthValue()<=11?"autumn":"winter",slot=slot(time.getHour());List<JSONObject> candidates=new ArrayList<>();
  JSONArray out=new JSONArray();for(int i=0;i<all.length();i++){JSONObject p=all.getJSONObject(i);String category=p.getString("category");if(used.contains(p.getString("id"))||wet&&!INDOOR.contains(category)||within!=null&&!within.contains(category)&&!(within.contains("nearby")&&nearby(p))||p.has("seasons")&&!MediaData.contains(p.optJSONArray("seasons"),season)||p.has("slots")&&!MediaData.contains(p.optJSONArray("slots"),slot))continue;
   if(category.equals("venue")){JSONArray names=p.optJSONArray("venues");boolean fits=venues.contains(p.optString("name"));if(names!=null)for(int n=0;n<names.length();n++)fits|=venues.contains(names.getString(n));if(fits&&out.length()<4)out.put(new JSONObject(p.toString()));}else candidates.add(p);
  }
  while(!candidates.isEmpty()&&out.length()<4){double total=0;for(JSONObject p:candidates)total+=weight(p,who,likes,within!=null);double draw=r.nextDouble()*total;int index=candidates.size()-1;for(int i=0;i<candidates.size();i++){draw-=weight(candidates.get(i),who,likes,within!=null);if(draw<0){index=i;break;}}out.put(new JSONObject(candidates.remove(index).toString()));}return out;
 }
 static double weight(JSONObject p,String who,JSONArray likes,boolean work){return work?1:(MediaData.contains(likes,p.optString("category"))?3:1)*(MediaData.contains(p.optJSONArray("idols"),who)?4:1);}
 static String map(JSONObject p,String provider)throws Exception{double lat=p.getDouble("lat"),lon=p.getDouble("lon");SocialData.coordinate(lat,lon);if(provider.equals("google"))return "https://www.google.com/maps/search/?api=1&query="+lat+","+lon;if(provider.equals("amap"))return "https://uri.amap.com/marker?position="+lon+","+lat+"&name="+URLEncoder.encode(p.getString("name"),"UTF-8")+"&coordinate=wgs84";return "https://www.openstreetmap.org/?mlat="+lat+"&mlon="+lon+"#map=17/"+lat+"/"+lon;}
 static JSONObject snapshot(JSONObject p)throws Exception{JSONObject out=new JSONObject();for(String k:new String[]{"id","name","area","lat","lon","category","note","source","checked"})if(p.has(k))out.put(k,p.get(k));return out;}
 static Set<String> workCategories(String activity){Set<String> out=new HashSet<>();if(activity.matches(".*(咖啡|甜品|餐厅|取材|飲食).*"))out.add("cafe");if(activity.matches(".*(服装|购物|衣装|逛街).*"))out.addAll(Arrays.asList("fashion-street","mall","shopping-street"));if(activity.matches(".*(外景|街拍|户外|ロケ).*"))out.addAll(Arrays.asList("park","shopping-street","seasonal"));return out;}
}
